def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}

    # Separator color appears most often in some complete separator row.
    line = max(colors, key=lambda color: max(row.count(color) for row in grid))
    separator_rows = [
        r for r, row in enumerate(grid)
        if row.count(line) >= 0.7 * w
    ]
    separator_cols = [
        c for c in range(w)
        if sum(grid[r][c] == line for r in range(h)) >= 0.7 * h
    ]

    background = max(
        (color for color in colors if color != line),
        key=lambda color: sum(row.count(color) for row in grid)
    )

    result = []
    for r1, r2 in zip(separator_rows, separator_rows[1:]):
        out_row = []
        for c1, c2 in zip(separator_cols, separator_cols[1:]):
            corners = [grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2]]
            marker = corners[0]
            if marker != line and marker != background and all(x == marker for x in corners):
                out_row.append(marker)
            else:
                out_row.append(background)
        result.append(out_row)
    return result
